  ('bf64bc21-860e-4cdb-b8f8-0b66edb319c6', 'a6b7c8d9-0e1f-4a03-8c33-3d4e5f6a7b03', null, 'topic'::public.curated_course_node_type, 'Stage Presence and Performance', 'Advanced performers must learn how to enter, breathe, focus, communicate, and leave the stage with intention. Stage presence combines preparation, embodiment, professionalism, and audience relationship.', 5),
