update public.learning_paths
set
  title = 'Applied Lessons (Advanced)',
  goal = 'Applied Lessons (Advanced)',
  summary = 'This course provides advanced private studio instruction focused on artistic maturity, technical refinement, repertoire development, interpretation, memorization, recital preparation, collaboration, recording, audition readiness, and pre-professional growth. Students develop a semester-long performance plan, document practice and self-evaluation, prepare advanced repertoire, collaborate with accompanists or ensemble partners, perform in studio-class and mock-audition settings, and assemble a portfolio that supports recitals, auditions, graduate study, or early professional opportunities.',
  data = $aplajson${"slug": "applied-lessons-advanced", "title": "Applied Lessons (Advanced)", "description": "This course provides advanced private studio instruction focused on artistic maturity, technical refinement, repertoire development, interpretation, memorization, recital preparation, collaboration, recording, audition readiness, and pre-professional growth. Students develop a semester-long performance plan, document practice and self-evaluation, prepare advanced repertoire, collaborate with accompanists or ensemble partners, perform in studio-class and mock-audition settings, and assemble a portfolio that supports recitals, auditions, graduate study, or early professional opportunities.", "topics": [{"id": "751685c9-e424-4600-bc9b-8dc6137f7062", "type": "topic", "title": "Advanced Repertoire", "description": "Advanced applied study asks students to move beyond pieces that merely display ability. Repertoire becomes a vehicle for artistic identity, historical understanding, technical growth, recital readiness, and professional positioning.", "children": [{"id": "36aa9703-8611-4d27-88e5-b600719c4c3e", "type": "subtopic", "title": "Repertoire selection", "children": [{"id": "e0dbea25-f940-48bd-825e-fef89e467b39", "type": "concept", "title": "Canonical works"}, {"id": "ac79e77c-9256-4bd9-89a1-7c87a55ce924", "type": "concept", "title": "Contemporary repertoire"}, {"id": "c5d6d8b9-13c3-4b3c-b7cc-a3c55952d7c1", "type": "concept", "title": "Underrepresented composers"}, {"id": "a45f2e14-09a9-4c23-806a-8f49d905ac38", "type": "concept", "title": "Level and readiness"}, {"id": "6d7f5259-5632-4946-8929-d705d8d42486", "type": "concept", "title": "Recital fit"}], "description": "Why learn it: Students learn to choose works that balance technical challenge, stylistic range, artistic depth, and long-term development."}, {"id": "4e50d2cb-260f-497d-9c48-0d76aea6f727", "type": "subtopic", "title": "Score study and context", "children": [{"id": "5a1f29b4-d81f-4f76-a4b7-328ff5ca1c69", "type": "concept", "title": "Composer background"}, {"id": "5bb1d863-d2a8-494f-8e9f-714d8a557bae", "type": "concept", "title": "Form and harmony"}, {"id": "d2b3147c-692b-4aae-99f6-b204193cce78", "type": "concept", "title": "Text and translation"}, {"id": "134bd4e9-b543-41a2-a62b-66d89d243192", "type": "concept", "title": "Historical editions"}, {"id": "a7f481e8-f59f-4906-996b-1905a7b26ef3", "type": "concept", "title": "Performance practice"}], "description": "Why learn it: The point is to understand the music before solving only the notes."}, {"id": "55dcfcad-715e-48d5-abb4-72e60fdbd8db", "type": "subtopic", "title": "Long-range repertoire planning", "children": [{"id": "4b11e211-6bc8-4446-84e0-5195595be2ef", "type": "concept", "title": "Short-term pieces"}, {"id": "500a17ea-3e88-491d-931f-42e99c09e2ca", "type": "concept", "title": "Major works"}, {"id": "d8e0736a-5dc6-497d-ab84-cc65497855cd", "type": "concept", "title": "Audition excerpts"}, {"id": "23c4d111-de3b-4b60-868b-177b96e41bfc", "type": "concept", "title": "Chamber works"}, {"id": "2cbaa2d7-8196-4f77-b46e-dc11686f49c6", "type": "concept", "title": "Maintenance repertoire"}], "description": "Why learn it: Students learn to pace learning across semesters, juries, auditions, recordings, and capstone recitals."}]}, {"id": "cfc574bd-5ee1-488b-b453-58e52e5e2c8c", "type": "topic", "title": "Refined Technique", "description": "At the advanced level, technique is not separate from artistry. Students refine the physical, aural, and expressive skills that make difficult music reliable, flexible, healthy, and communicative.", "children": [{"id": "ac5a62db-6013-4085-8a86-6e9d24777737", "type": "subtopic", "title": "Technical diagnosis", "children": [{"id": "78c198f6-6d53-41fd-8668-ff7bb1aa5188", "type": "concept", "title": "Tone production"}, {"id": "57ce2639-76c6-436b-af7e-e966e9cceff9", "type": "concept", "title": "Intonation"}, {"id": "1e7ceb8a-68af-475a-996b-69ebed9939a4", "type": "concept", "title": "Rhythm stability"}, {"id": "b89a0265-96d8-4b16-babb-45ffed1d0dad", "type": "concept", "title": "Articulation"}, {"id": "f78fa914-794d-4bce-a208-648309a820e1", "type": "concept", "title": "Registration or range"}], "description": "Why learn it: Students learn to identify the root cause of technical issues rather than repeating inefficient practice."}, {"id": "bf5213aa-7ad1-46ce-ba50-4424b3e50c99", "type": "subtopic", "title": "Deliberate practice systems", "children": [{"id": "2abe031b-90e4-465f-8283-08102e153a55", "type": "concept", "title": "Slow practice"}, {"id": "cd9ac626-78de-4b06-bdd3-f6317f52e2c8", "type": "concept", "title": "Chunking"}, {"id": "e6492c2b-195e-4909-acec-d7103d62c96f", "type": "concept", "title": "Variation practice"}, {"id": "587a0ad3-2d8c-482c-8960-eede6ad9027f", "type": "concept", "title": "Metronome ladders"}, {"id": "1bd337f6-a2b0-4d99-8604-96b1155c692a", "type": "concept", "title": "Practice journaling"}], "description": "Why learn it: Students build repeatable practice methods that are efficient, measurable, and musically connected."}, {"id": "1d61a9ac-74ab-4315-98d9-76ce08830b16", "type": "subtopic", "title": "Body use and injury prevention", "children": [{"id": "af58a76f-fd89-4dd8-be32-55eb3348c52e", "type": "concept", "title": "Body mapping"}, {"id": "44db5d91-d1c5-4bc1-a91c-5f08ed47bf1f", "type": "concept", "title": "Posture and alignment"}, {"id": "f609070d-d434-4bf4-9e9b-a6ddd7ca706e", "type": "concept", "title": "Warmups and cooldowns"}, {"id": "258d3783-cad2-4573-93ac-b2d92857ed04", "type": "concept", "title": "Fatigue tracking"}, {"id": "697b7f9f-2b7a-4dee-ad98-2c4d004cd592", "type": "concept", "title": "Pain response"}], "description": "Why learn it: Students connect advanced technique to efficient movement, recovery, and sustainable musicianship."}]}, {"id": "cc453741-8387-4ab3-906b-5f8828c47db4", "type": "topic", "title": "Interpretation and Style", "description": "Interpretation is where technical control becomes musical argument. Students learn to make informed choices about phrasing, sound, gesture, text, style, and expressive timing.", "children": [{"id": "7c62dbe2-d57a-4dd9-8eba-e08568bfe8e8", "type": "subtopic", "title": "Stylistic fluency", "children": [{"id": "e5e1edac-691d-466c-a4c4-df3bd9b6ea84", "type": "concept", "title": "Baroque rhetoric"}, {"id": "c7638d7b-41da-420a-bb13-ff61a7b012ee", "type": "concept", "title": "Classical proportion"}, {"id": "de65021a-f0e5-4b9e-a3c9-958d5f651fb0", "type": "concept", "title": "Romantic rubato"}, {"id": "edf6fc35-5d07-42b7-83a5-ed37e74bbad1", "type": "concept", "title": "Modernist color"}, {"id": "4e22ae80-afd9-42ae-96c8-42d77173ba27", "type": "concept", "title": "Jazz or vernacular inflection"}], "description": "Why learn it: Students learn how different periods and genres ask for different sound worlds and expressive rules."}, {"id": "bd8d8f7a-e010-49de-9c82-e27d51fccb8c", "type": "subtopic", "title": "Phrasing and musical narrative", "children": [{"id": "feb96a12-a290-4606-bdd3-88cb8357b888", "type": "concept", "title": "Line and breath"}, {"id": "5f041622-f69e-4b76-b17f-ebdee780ade3", "type": "concept", "title": "Cadence awareness"}, {"id": "0625f47f-17be-4a8f-839a-ee4192409949", "type": "concept", "title": "Dynamic architecture"}, {"id": "a74ed22b-0be4-4ac3-a750-0c3b3c048742", "type": "concept", "title": "Tempo flexibility"}, {"id": "8bfd8638-1614-4459-b5ab-ea9583885047", "type": "concept", "title": "Silence and pacing"}], "description": "Why learn it: Students practice shaping music so listeners can hear direction, tension, release, and character."}, {"id": "94d88963-53ad-4e49-a82e-3a9594a53295", "type": "subtopic", "title": "Interpretive research", "children": [{"id": "b283998f-d2ab-4913-9e89-f6acd313098d", "type": "concept", "title": "Reference recordings"}, {"id": "20063317-a898-45be-a970-9e74ea5c4d32", "type": "concept", "title": "Critical editions"}, {"id": "c52a7326-cc3d-4118-92d3-5a0824908c7b", "type": "concept", "title": "Teacher lineage"}, {"id": "fca0b473-c83a-4ca1-b019-a439836c9305", "type": "concept", "title": "Performance-practice sources"}, {"id": "5116c678-1f5f-46ae-b872-af2016c22362", "type": "concept", "title": "Artist statements"}], "description": "Why learn it: Students use recordings, editions, treatises, and coachings as evidence while developing their own voice."}]}, {"id": "458e4cdf-274d-49e9-b473-fde599bd9fd0", "type": "topic", "title": "Memorization", "description": "Memorization is not only muscle memory; it is musical, analytical, physical, aural, and psychological security. Students learn systems that make performance under pressure more dependable.", "children": [{"id": "d1235583-16f2-4a3e-b9d1-e1df0b043c1d", "type": "subtopic", "title": "Types of memory", "children": [{"id": "854f55fc-b41f-482e-90df-3bdc7056fe72", "type": "concept", "title": "Aural memory"}, {"id": "1302dbb1-84d2-4d44-b513-df9a49477b54", "type": "concept", "title": "Visual memory"}, {"id": "39788209-8d25-4ecf-a352-a4173e7ab579", "type": "concept", "title": "Analytical memory"}, {"id": "2868c0f5-7923-4f8b-b6e8-b31a671f2d74", "type": "concept", "title": "Kinesthetic memory"}, {"id": "6aefecfe-79e9-4b89-bb5d-f88b2cc79b89", "type": "concept", "title": "Text memory"}], "description": "Why learn it: Students understand how different memory systems support one another in performance."}, {"id": "d7a936c6-43b5-456c-87c0-bd982670d0e4", "type": "subtopic", "title": "Memory practice strategies", "children": [{"id": "76d1b143-095e-4053-b197-e60f6e84a42d", "type": "concept", "title": "Backward chaining"}, {"id": "9a40ca81-339e-4305-ad9d-d0c57976409b", "type": "concept", "title": "Starting points"}, {"id": "5138314c-e6a3-47a8-9ef1-5014bb76a872", "type": "concept", "title": "Silent practice"}, {"id": "1aebb0c1-b617-4e12-b545-06f16e89f75f", "type": "concept", "title": "Score-free analysis"}, {"id": "953369c3-086a-4291-92d8-b6b16257fe60", "type": "concept", "title": "Distraction practice"}], "description": "Why learn it: Students learn to test memory actively before the pressure of recital or audition."}, {"id": "8fce2563-9d29-42b0-960d-4abb4d307f2b", "type": "subtopic", "title": "Recovery and resilience", "children": [{"id": "6480736e-5d44-45d2-abbc-2284c8d64f6e", "type": "concept", "title": "Memory maps"}, {"id": "c078e6bb-3dd2-46fc-a540-fa753ab649bd", "type": "concept", "title": "Harmonic anchors"}, {"id": "2ed9a6e7-85e2-43c6-b582-5abe66618610", "type": "concept", "title": "Breath resets"}, {"id": "f370b820-e475-4ac6-b5c3-f81bfa24e33f", "type": "concept", "title": "Skip-forward plans"}, {"id": "fcf20dee-7ec4-4734-98f5-06928f28ba60", "type": "concept", "title": "Mock performance"}], "description": "Why learn it: Students prepare for slips by building recovery points and calm responses."}]}, {"id": "1eb52af1-0f6a-421c-86d0-a38ef377f119", "type": "topic", "title": "Recital Programming", "description": "A recital is an artistic statement, not a pile of pieces. Students learn to design programs that show range, coherence, historical breadth, personal voice, and audience awareness.", "children": [{"id": "62b2d8ff-87c9-46d6-a7b5-3d2d54d63323", "type": "subtopic", "title": "Program design", "children": [{"id": "e6093460-a856-4839-b9ca-ea1f3be79570", "type": "concept", "title": "Opening and closing works"}, {"id": "30c3cc2c-0f12-49ca-9c93-3c343a890a3b", "type": "concept", "title": "Contrast of style"}, {"id": "ffaba846-67d8-461e-ba6d-99e839f601e0", "type": "concept", "title": "Key and tempo relationships"}, {"id": "d373aefd-356d-430f-855b-567b982a67f5", "type": "concept", "title": "Audience energy"}, {"id": "b0ca4c36-5024-4ae4-bbaa-954174c0d7f8", "type": "concept", "title": "Program duration"}], "description": "Why learn it: Students learn to balance contrast, pacing, difficulty, length, and artistic identity."}, {"id": "d34f94b7-3791-4c06-a04b-1d28f39b6986", "type": "subtopic", "title": "Repertoire equity and representation", "children": [{"id": "610b6db7-a869-4878-a644-a8ee57affa01", "type": "concept", "title": "Women composers"}, {"id": "6202f1b2-ff85-4f1c-9cc0-39c5b5c80f18", "type": "concept", "title": "Composers of color"}, {"id": "210b0fb7-6fde-4323-a60d-df3d395ff1bb", "type": "concept", "title": "Living composers"}, {"id": "2cc9ee75-2a7b-4209-89eb-8c05bb5e72f0", "type": "concept", "title": "Cultural context"}, {"id": "a43e64c4-de07-4fd1-b6e1-601e80266ab1", "type": "concept", "title": "Ethical research"}], "description": "Why learn it: Students consider whose music is programmed and why."}, {"id": "9b7e4e7a-06ca-40af-afcd-86c7e1279464", "type": "subtopic", "title": "Program notes and speaking", "children": [{"id": "8426f3a8-2b52-4a2d-bc44-a06dd2cc26d2", "type": "concept", "title": "Program-note structure"}, {"id": "1549acba-b553-47fd-8294-9fc865c87367", "type": "concept", "title": "Translations"}, {"id": "9c1e6c46-9389-4c37-9771-959cce328da2", "type": "concept", "title": "Composer notes"}, {"id": "b60b8642-540e-45ff-9d08-3045c20044ac", "type": "concept", "title": "Audience address"}, {"id": "9b9ab26f-8fb5-45af-8179-5fae6aa0f53b", "type": "concept", "title": "Citation habits"}], "description": "Why learn it: Students learn to communicate context without flattening the music or overloading the audience."}]}, {"id": "bf64bc21-860e-4cdb-b8f8-0b66edb319c6", "type": "topic", "title": "Stage Presence and Performance", "description": "Advanced performers must learn how to enter, breathe, focus, communicate, and leave the stage with intention. Stage presence combines preparation, embodiment, professionalism, and audience relationship.", "children": [{"id": "e75f2304-dd41-4d51-8b08-e2e76568a9df", "type": "subtopic", "title": "Performance routine", "children": [{"id": "6c364827-5265-475e-9aa9-80c4fb8583ae", "type": "concept", "title": "Day-of planning"}, {"id": "3aa2d44c-f96f-413d-8547-712853043fe8", "type": "concept", "title": "Warmup sequence"}, {"id": "a4d13c28-3178-402e-b8ad-d4a23b461509", "type": "concept", "title": "Mental focus"}, {"id": "ecc195a7-b541-47b3-924d-5ac3eb0eff21", "type": "concept", "title": "Green room habits"}, {"id": "6a7219c4-132a-42b6-88e6-cc0473ed251c", "type": "concept", "title": "Post-performance notes"}], "description": "Why learn it: Students build pre-performance and post-performance habits that support consistency."}, {"id": "edf3b38f-c270-41ae-901d-bb9c1cee8344", "type": "subtopic", "title": "Physical and visual communication", "children": [{"id": "76fe8b83-933b-47d5-9246-6882afa1f5a3", "type": "concept", "title": "Entrance and bow"}, {"id": "bd29591b-7ef7-4f6b-bbd0-cdc1b0884f25", "type": "concept", "title": "Music stand setup"}, {"id": "055b5f2c-00fc-445d-a9b8-c3a2cd50182e", "type": "concept", "title": "Facial focus"}, {"id": "08afe0aa-a248-4aec-9cac-670bdb752315", "type": "concept", "title": "Movement economy"}, {"id": "16e44a4e-14aa-409a-bf65-cdb2ad7f0dd2", "type": "concept", "title": "Professional attire"}], "description": "Why learn it: Students learn how gesture, stillness, eye line, dress, and transitions affect the listener's experience."}, {"id": "653b1d68-6baa-404d-86c0-f31d6bfc5472", "type": "subtopic", "title": "Performance psychology", "children": [{"id": "457bd9b8-6ba6-4d93-836c-b72ca92e30d3", "type": "concept", "title": "Arousal regulation"}, {"id": "c6e30490-6b59-4410-9a65-b35f9598f485", "type": "concept", "title": "Self-talk"}, {"id": "bb51ac66-2bd9-4f84-94c5-ad411990df30", "type": "concept", "title": "Breathing"}, {"id": "2af2c38c-afd1-4901-80e1-d04edbff766b", "type": "concept", "title": "Visualization"}, {"id": "49215fd8-06da-4658-b526-f8938918761f", "type": "concept", "title": "Pressure simulation"}], "description": "Why learn it: Students develop tools for focus, confidence, and anxiety management."}]}, {"id": "f42acee7-a669-48a2-99f7-c87c092e9304", "type": "topic", "title": "Collaboration with Accompanists and Ensembles", "description": "Advanced applied musicianship is collaborative. Students learn how to rehearse with pianists, chamber partners, conductors, coaches, and recording collaborators with preparation and respect.", "children": [{"id": "d4d207a9-fbae-4268-b38e-70d31967fe05", "type": "subtopic", "title": "Collaborative preparation", "children": [{"id": "633ce9e3-647a-432a-b09d-b1c3d5cf20b5", "type": "concept", "title": "Score sharing"}, {"id": "cbc022a8-633d-4604-ade2-721537794c8a", "type": "concept", "title": "Tempo planning"}, {"id": "008da2b7-0233-4c5a-a1e7-cf0ccc417255", "type": "concept", "title": "Cue awareness"}, {"id": "06750320-f25f-4072-86b4-85963388c386", "type": "concept", "title": "Rehearsal markings"}, {"id": "6bc31b8d-9ee7-4a30-ac3e-ad9513f8cc8d", "type": "concept", "title": "Translation and text notes"}], "description": "Why learn it: Students learn what to prepare before the first rehearsal so rehearsal time can become musical rather than logistical."}, {"id": "9fbb3200-0833-47ad-9a6b-d9c23cf5934a", "type": "subtopic", "title": "Rehearsal communication", "children": [{"id": "82cfe217-a803-4fa9-acdc-53e5e814a529", "type": "concept", "title": "Listening across parts"}, {"id": "d155b21c-2ba9-4966-ae5c-743352ecbcf4", "type": "concept", "title": "Balance"}, {"id": "bc9d2086-f627-43b0-bc1c-85e385bbd1ff", "type": "concept", "title": "Intonation negotiation"}, {"id": "7865c6e0-85d8-4046-b879-52c4a35425ec", "type": "concept", "title": "Rubato coordination"}, {"id": "8389abed-a1c2-4722-9fcb-fec8297aa2c3", "type": "concept", "title": "Rehearsal etiquette"}], "description": "Why learn it: Students practice concise, respectful language for solving ensemble problems."}, {"id": "817f435f-336c-49b1-98fc-752df03aeb74", "type": "subtopic", "title": "Professional collaboration logistics", "children": [{"id": "e2f8b2e9-2414-470f-be20-5eefa845c281", "type": "concept", "title": "Scheduling"}, {"id": "e559881f-06c6-4750-9724-ec69c245892e", "type": "concept", "title": "Payment norms"}, {"id": "1938fe03-b3b8-46d6-beb6-9177958090b7", "type": "concept", "title": "Recording permissions"}, {"id": "6e6e1f2e-1fc0-4c00-b608-cb8a31015fe0", "type": "concept", "title": "Dress rehearsal plans"}, {"id": "d68a3f54-7eb5-469c-8d04-754e187e2637", "type": "concept", "title": "Thank-you and crediting"}], "description": "Why learn it: Students learn the practical systems that protect relationships and deadlines."}]}, {"id": "1c4e7ac1-1da6-4148-94ca-f9a2f67724a9", "type": "topic", "title": "Recording and Self-Evaluation", "description": "Recording gives students evidence. Advanced students learn to listen without panic or vanity, diagnose performance patterns, and use recordings for auditions, portfolios, and artistic growth.", "children": [{"id": "73c6a708-14f2-4b0d-868d-bce096b4821a", "type": "subtopic", "title": "Recording setup", "children": [{"id": "d5c6c6a1-7aa0-4509-8df4-10d093697883", "type": "concept", "title": "Room choice"}, {"id": "39cd632f-573d-463f-ba73-2ac357041ca7", "type": "concept", "title": "Microphone placement"}, {"id": "1a374510-35f4-4b2d-8ef6-47e5600439b1", "type": "concept", "title": "Camera framing"}, {"id": "d2826ea2-6957-4a8a-a37c-f0a88543b850", "type": "concept", "title": "File formats"}, {"id": "ac25b4ea-601c-4b2e-b2ec-678c673c2607", "type": "concept", "title": "Take labeling"}], "description": "Why learn it: Students learn basic audio/video choices that produce usable documentation."}, {"id": "53ecb431-dd45-4e2e-917c-14aacd069063", "type": "subtopic", "title": "Self-evaluation protocols", "children": [{"id": "a9b8fa67-2467-487f-ac7b-aac919afffee", "type": "concept", "title": "First impression notes"}, {"id": "ca400ae2-7af7-4f2c-9d39-b0976a166dfa", "type": "concept", "title": "Timestamp comments"}, {"id": "b22cb27c-699a-4acf-bed6-673c58c4f54e", "type": "concept", "title": "Rubric listening"}, {"id": "6a02b551-4800-4d99-a37e-b45c419c324a", "type": "concept", "title": "Before/after comparisons"}, {"id": "a970b714-b684-42ab-aa04-03c0c582b3e5", "type": "concept", "title": "Teacher conference clips"}], "description": "Why learn it: Students develop focused listening habits that turn recordings into productive practice data."}, {"id": "45ce73e9-e60e-496d-9d7e-26c1e62fe853", "type": "subtopic", "title": "Portfolio recordings", "children": [{"id": "4d81073e-3745-4296-a23f-581fd6165ced", "type": "concept", "title": "Repertoire excerpts"}, {"id": "e77d5848-70e5-4627-8664-9f70be27d706", "type": "concept", "title": "Complete takes"}, {"id": "2dd5b5e7-4529-4886-bc00-2111bc57d65f", "type": "concept", "title": "Editing ethics"}, {"id": "0771cc04-d9e9-4834-8a61-98a2b81ab15f", "type": "concept", "title": "Metadata"}, {"id": "1b42c816-c014-4836-b8cc-3fef4569047f", "type": "concept", "title": "Submission requirements"}], "description": "Why learn it: Students learn how recordings support auditions, graduate applications, competitions, and professional outreach."}]}, {"id": "c573e680-70ac-4443-bbf5-1a66c6592e29", "type": "topic", "title": "Audition Preparation", "description": "Audition preparation requires more than learning excerpts. Students learn to prepare requirements, simulate pressure, manage logistics, and communicate readiness in competitive settings.", "children": [{"id": "72b7a023-d781-4ba2-8a2f-d0d2d6744b64", "type": "subtopic", "title": "Audition materials", "children": [{"id": "9908f76d-b2ad-4e7b-81a0-538f87e7d04b", "type": "concept", "title": "Excerpt lists"}, {"id": "dd598089-f7ef-4a63-b7f5-8a08a82277cc", "type": "concept", "title": "Contrasting works"}, {"id": "0dcee1b5-f6ba-4932-8345-44cbddedd406", "type": "concept", "title": "Prescreen videos"}, {"id": "f3ed32d7-d06e-49a0-bc88-b95bb29cfb2e", "type": "concept", "title": "Resume and repertoire list"}, {"id": "1bff512c-8602-4ecb-868b-dbb86e122b6e", "type": "concept", "title": "Application deadlines"}], "description": "Why learn it: Students learn how to select, prepare, and maintain audition repertoire for specific opportunities."}, {"id": "08f6872a-d288-4d1a-a3e8-7ec981e8d6fa", "type": "subtopic", "title": "Mock audition process", "children": [{"id": "aefaef3d-7218-4334-8238-7fa252062cd2", "type": "concept", "title": "Screen format"}, {"id": "1dca0082-b4c7-4aec-a18d-656b63965f87", "type": "concept", "title": "Time limits"}, {"id": "8a4e8912-04e1-4c90-b87b-6cc313ffe02e", "type": "concept", "title": "Panel etiquette"}, {"id": "90dfef70-7908-4509-962b-514c70936ec2", "type": "concept", "title": "Random starts"}, {"id": "2baeb721-efdf-4a81-8dd1-b5aa94e8745d", "type": "concept", "title": "Feedback integration"}], "description": "Why learn it: Students practice performing under realistic constraints and receiving actionable feedback."}, {"id": "e6930a27-4fe7-419a-9918-169647163ad1", "type": "subtopic", "title": "Audition-day strategy", "children": [{"id": "1706ac32-6e13-466c-95e4-0748182ad1f7", "type": "concept", "title": "Travel planning"}, {"id": "9b9740cc-5239-4ba6-af5a-f778209f61a5", "type": "concept", "title": "Warmup rooms"}, {"id": "8843cb2f-090f-4151-9cea-5d7bcf80ef23", "type": "concept", "title": "Food and hydration"}, {"id": "60cfa13d-1222-48bb-bb7d-1ea776ce50a7", "type": "concept", "title": "Instrument care"}, {"id": "0350f626-01b9-4ac2-9680-9f8b34525fe7", "type": "concept", "title": "Post-audition reflection"}], "description": "Why learn it: Students learn logistics and mindset habits that reduce avoidable errors."}]}, {"id": "e5c8f2ad-ac1d-4ea7-bf62-fab38e29013f", "type": "topic", "title": "Pre-Professional Development", "description": "Advanced applied lessons should prepare students for life after the degree. Students develop professional habits, portfolio materials, career literacy, and a sustainable artistic identity.", "children": [{"id": "8b9ab22f-4b43-485d-8645-42ab0ad83477", "type": "subtopic", "title": "Professional identity", "children": [{"id": "b3ac0a7e-e756-4936-9678-489297ae3a2f", "type": "concept", "title": "Artist statement"}, {"id": "017d6318-cddb-476b-994d-cbfa7c15b1fe", "type": "concept", "title": "Bio"}, {"id": "6e52d7e1-1e2c-409b-b2a3-97d8b1502ad3", "type": "concept", "title": "Repertoire identity"}, {"id": "14dd6c